PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, sort INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN(0,1)));
CREATE TABLE IF NOT EXISTS tags(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, slug TEXT NOT NULL UNIQUE, sort INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN(0,1)));
CREATE TABLE IF NOT EXISTS media(key TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL, size INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tools(id INTEGER PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', icon TEXT NOT NULL DEFAULT '', category_id INTEGER REFERENCES categories(id) ON DELETE SET NULL, sort INTEGER NOT NULL DEFAULT 0, category_sort INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN(0,1)));
CREATE TABLE IF NOT EXISTS tool_tags(tool_id INTEGER NOT NULL REFERENCES tools(id) ON DELETE CASCADE, tag_id INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE, sort INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(tool_id,tag_id));
CREATE TABLE IF NOT EXISTS search_engines(id INTEGER PRIMARY KEY, name TEXT NOT NULL, url_template TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', icon TEXT NOT NULL DEFAULT '', sort INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN(0,1)));
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1), title TEXT NOT NULL DEFAULT 'Diaopicks', description TEXT NOT NULL DEFAULT '', favicon TEXT NOT NULL DEFAULT '/placeholder.svg', new_tab INTEGER NOT NULL DEFAULT 1, columns INTEGER NOT NULL DEFAULT 4 CHECK(columns BETWEEN 2 AND 6), show_engines INTEGER NOT NULL DEFAULT 1, compact INTEGER NOT NULL DEFAULT 0, no_images INTEGER NOT NULL DEFAULT 0, notice TEXT NOT NULL DEFAULT '本站部分链接包含返利或邀请关系，已标注 Aff。请按实际需要选择，理性消费。');
CREATE TABLE IF NOT EXISTS publication(id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL DEFAULT 1, published_revision INTEGER NOT NULL DEFAULT 0, published_at TEXT, last_error TEXT);
INSERT OR IGNORE INTO settings(id) VALUES(1);
INSERT OR IGNORE INTO publication(id) VALUES(1);
CREATE INDEX IF NOT EXISTS tools_category_sort ON tools(category_id,category_sort,sort);
CREATE INDEX IF NOT EXISTS tool_tags_tag ON tool_tags(tag_id,tool_id);
